def _canonical(value):
    """配置值规范化：各层对象键按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        return {key: _canonical(value[key]) for key in sorted(value)}
    if isinstance(value, list):
        return [_canonical(item) for item in value]
    return value


